export function normalizeArabic(s){return String(s).replace(/[٠-٩]/g,c=>String("٠١٢٣٤٥٦٧٨٩".indexOf(c))).replace(/[۰-۹]/g,c=>String("۰۱۲۳۴۵۶۷۸۹".indexOf(c))).replace(/[أإآ]/g,"ا").replace(/[\u064B-\u065F]/g,"").trim()}
export function parseFree(text){const s=normalizeArabic(text),out=[];const add=(id,value,evidence)=>out.push({id,value,evidence});const nums={"واحد":1,"واحدة":1,"اثنين":2,"اثنان":2,"ثلاث":3,"ثلاثة":3,"اربع":4,"اربعة":4,"خمس":5,"خمسة":5,"ست":6,"ستة":6};const number=x=>/^\d+$/.test(x)?Number(x):nums[x];for(const [id,re] of [["household.children",/(?:عندي|معي|لدينا)\s+(\d+|واحد|اثنين|ثلاثة|ثلاث|اربعة|اربع|خمسة|خمس|ستة|ست)\s+(?:عيال|ابناء|اطفال)/g],["household.bedrooms",/(\d+|واحدة|اثنين|ثلاثة|ثلاث|اربعة|اربع|خمسة|خمس|ستة|ست)\s+غرف(?:ة)?\s+نوم/g],["budget.count",/(\d+|واحد|اثنين|ثلاثة|ثلاث|اربعة|اربع|خمسة|خمس|ستة|ست)\s+(?:تصاميم|تصميم|بدائل|بديل)/g]])for(const m of s.matchAll(re))add(id,number(m[1]),m[0]);if(/(?:ابي|اريد|ابغى)\s+تصميم\s+واحد/.test(s))add("budget.count",1,"تصميم واحد");if(/(?:ما عندي|ليس لدي|بدون)\s+(?:عيال|ابناء|اطفال)/.test(s))add("household.children",0,"لا يوجد أبناء");const unique=new Map();const ambiguous=new Set();for(const p of out){if(unique.has(p.id)&&unique.get(p.id).value!==p.value)ambiguous.add(p.id);unique.set(p.id,p)}return {proposals:[...unique.values()].filter(p=>!ambiguous.has(p.id)),ambiguous:[...ambiguous],originalText:String(text)}}
export function qualityReview(plan,policy={}){const limits={livingRatio:2,serviceWalkM:12,guestWalkM:8,...policy};const findings=[];const add=(id,status,measured,reason)=>findings.push({id,status,measured,reason});const rooms=Array.isArray(plan?.rooms)?plan.rooms:[];const living=rooms.filter(r=>r.role==="living");if(!living.length)add("living-proportion","NOT_EVALUATED",null,"لا توجد أبعاد صالة صافية");for(const r of living){const w=r.clearWidthM,d=r.clearDepthM;if(!(Number.isFinite(w)&&Number.isFinite(d)&&w>0&&d>0)||r.rectangular!==true){add("living-proportion:"+r.id,"NOT_EVALUATED",null,"يلزم قياس صافي مستطيل أو تحليل مضلع");continue}const ratio=Math.max(w,d)/Math.min(w,d);add("living-proportion:"+r.id,ratio>limits.livingRatio?"REVIEW_REQUIRED":"PASS",ratio,"نسبة الاستطالة؛ معيار تصميمي قابل للمعايرة وليس اشتراطًا نظاميًا")}
const paths=plan?.paths||{};for(const [id,max] of [["kitchenDining",limits.serviceWalkM],["maleMajlisDining",limits.guestWalkM]]){const p=paths[id];if(!p||p.verified!==true||!Number.isFinite(p.lengthM)||p.lengthM<0||!Array.isArray(p.zones)){add(id,"NOT_EVALUATED",null,"يلزم مسار مشي موثق من الأبواب");continue}add(id,p.lengthM>max||p.zones.includes("family_private")?"REVIEW_REQUIRED":"PASS",p.lengthM,"طول مسار المشي وعدم عبور المنطقة الخاصة")}
const e=plan?.entrances;if(!e||e.verified!==true||!e.maleDoorId||!e.femaleDoorId||!Array.isArray(e.maleZones)||!Array.isArray(e.femaleZones)){add("separate-entries","NOT_EVALUATED",null,"يلزم إثبات البابين ومساري الحركة")}else{const overlap=e.maleZones.filter(z=>e.femaleZones.includes(z)&&z!=="outside");add("separate-entries",e.maleDoorId===e.femaleDoorId||overlap.length?"REVIEW_REQUIRED":"PASS",overlap,"فصل المداخل والمسارات الداخلية")}
for(const id of ["daylight","ventilation","visualPrivacy","imageGeometryConsistency"])add(id,"NOT_EVALUATED",null,"يحتاج تحليل هندسي أو دليل مستقل؛ لا يُستنتج من جمال الصورة");return {status:findings.some(f=>f.status==="REVIEW_REQUIRED")?"REVIEW_REQUIRED":findings.some(f=>f.status==="NOT_EVALUATED")?"NOT_EVALUATED":"PASS",findings,policy:limits,engineeringApproval:false}}
